/* Parameter sweeps and snapshots operate on the experiment's native controls. */
(()=>{'use strict';const tools=new WeakMap(),motion=matchMedia('(prefers-reduced-motion: reduce)'),running=new Map();
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
function text(n){const c=n.cloneNode(true);c.querySelectorAll('.inline-math[data-inline-raw]').forEach(n=>n.replaceWith(document.createTextNode(n.dataset.inlineRaw)));c.querySelectorAll('.katex').forEach(n=>n.replaceWith(document.createTextNode(n.querySelector('.katex-html')?.textContent||'')));c.querySelectorAll('output,select,.glossary-ui').forEach(n=>n.remove());return c.textContent.trim();}
function cells(page){const rows=[...page.querySelectorAll('.readout-row>div,.readouts>div,.extension-readouts>div,#reservoirs>div')].filter(n=>n.querySelector('strong')).map(n=>({label:text(n.querySelector('span')||n),value:text(n.querySelector('strong'))}));page.querySelectorAll('#clock-chart circle').forEach(n=>{const d=d3.select(n).datum();if(d&&Number.isFinite(d.value))rows.push({label:d.label+'（Gyr）',value:d.value.toLocaleString('zh-CN',{maximumSignificantDigits:6})});});return rows;}
const numeric=s=>{const raw=s.replaceAll(',','').replace(/%$/,'').trim();return /^[+−-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+−-]?\d+)?$/i.test(raw)?Number(raw.replace('−','-')):null;};
function stop(page){const run=running.get(page);if(!run)return;cancelAnimationFrame(run.frame);running.delete(page);run.button.textContent='扫描所选参数';run.button.setAttribute('aria-pressed','false');}
let drawer,launcher,drawerTitle,drawerBody,closeButton,opened;
function closeDrawer(focus=false){if(!opened)return;const current=opened;stop(current.page);current.details.hidden=true;current.details.open=false;current.anchor.before(current.details);opened=null;drawer.hidden=true;document.body.classList.remove('lab-tools-open');window.dispatchEvent(new Event('resize'));launcher.setAttribute('aria-expanded','false');if(focus&&!launcher.hidden)launcher.focus();}
function syncDrawer(){const page=document.querySelector('.reader-slide.is-active');launcher.hidden=!page||!tools.has(page);}
function openDrawer(){const page=document.querySelector('.reader-slide.is-active'),tool=tools.get(page);if(!tool)return;closeDrawer();opened={...tool,page};drawerTitle.textContent=text(page.querySelector('h3,h2')||page.querySelector('.reader-context')||page);drawer.dataset.glossaryContext=page.querySelector('.lab[id],.extension-lab[id]')?.id||page.dataset.pageTarget;drawerBody.append(tool.details);tool.details.hidden=false;tool.details.open=true;drawer.hidden=false;document.body.classList.add('lab-tools-open');window.dispatchEvent(new Event('resize'));launcher.setAttribute('aria-expanded','true');tool.sync();closeButton.focus();}
function createDrawer(){if(drawer)return;launcher=el('button','lab-tools-launcher','实验工具');launcher.type='button';launcher.hidden=true;launcher.setAttribute('aria-label','打开参数扫描与读数对照');launcher.setAttribute('aria-expanded','false');launcher.setAttribute('aria-controls','lab-tools-panel');drawer=el('aside','lab-tools-panel');drawer.id='lab-tools-panel';drawer.hidden=true;drawer.setAttribute('aria-labelledby','lab-tools-heading');const header=el('header','lab-tools-header'),title=el('h2','','参数扫描与读数对照');title.id='lab-tools-heading';closeButton=el('button','lab-tools-close','×');closeButton.type='button';closeButton.setAttribute('aria-label','关闭实验工具');header.append(title,closeButton);drawerTitle=el('p','lab-tools-context');drawerBody=el('div','lab-tools-body');drawer.append(header,drawerTitle,drawerBody);document.body.append(launcher,drawer);launcher.onclick=()=>opened?closeDrawer(true):openDrawer();closeButton.onclick=()=>closeDrawer(true);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&opened&&!event.defaultPrevented&&!document.querySelector('dialog[open],.glossary-card')){event.preventDefault();closeDrawer(true);}});}
function attach(page){if(tools.has(page))return;const inputs=[...page.querySelectorAll('input[type=range]')];if(!inputs.length)return;const controls=[...inputs,...page.querySelectorAll('select[id]')].filter(n=>!n.closest('.curve-explorer,.disk-brush,.lab-workbench'));
const details=el('details','lab-workbench'),summary=el('summary','','参数扫描与读数对照'),row=el('div','lab-workbench-actions'),label=el('label','','扫描参数'),select=el('select'),sweep=el('button','','扫描所选参数'),pin=el('button','','记录当前读数'),clear=el('button','','清除记录'),progress=el('progress'),note=el('p','lab-tool-note','扫描只改变所选参数；动画进度不是物理时间。可随时拖动原滑块接管。'),results=el('div','lab-snapshot');
select.setAttribute('aria-label','选择扫描参数');for(const input of inputs){const option=new Option(text(page.querySelector(`label[for="${CSS.escape(input.id)}"]`)||input.parentElement),input.id);select.append(option);}label.append(select);for(const b of [sweep,pin,clear])b.type='button';sweep.setAttribute('aria-pressed','false');clear.hidden=true;progress.max=1;progress.value=0;progress.setAttribute('aria-label','参数扫描进度');row.append(label,sweep,pin,clear);details.append(summary,row,progress,note,results);const anchor=document.createComment('experiment tools');page.append(details,anchor);details.hidden=true;let saved;
const manual=el('label','lab-manual-control','手动调整所选参数'),manualValue=el('output'),manualInput=el('input');manualInput.type='range';manualInput.setAttribute('aria-label','调整所选参数');manual.append(manualValue,manualInput);label.after(manual);
function sync(){const input=inputs.find(n=>n.id===select.value);for(const attr of ['min','max','step'])manualInput.setAttribute(attr,input.getAttribute(attr)||'1');manualInput.value=input.value;manualInput.disabled=sweep.disabled=input.disabled;manualValue.textContent=input.getAttribute('aria-valuetext')||input.value;}
manualInput.addEventListener('input',()=>{stop(page);const input=inputs.find(n=>n.id===select.value);if(input.disabled)return;input.value=manualInput.value;input.dispatchEvent(new Event('input',{bubbles:true}));sync();});manualInput.addEventListener('change',()=>inputs.find(n=>n.id===select.value).dispatchEvent(new Event('change',{bubbles:true})));controls.forEach(input=>input.addEventListener('input',sync));sync();
function update(){if(!saved)return;const now=cells(page),table=el('table','lab-comparison-table'),head=el('thead'),hr=el('tr');for(const title of ['读数','记录','当前','差值'])hr.append(el('th','',title));head.append(hr);table.append(head);const body=el('tbody');now.forEach((cell,i)=>{const old=saved.rows.find(row=>row.label===cell.label);if(!old)return;const row=el('tr'),a=numeric(old.value),b=numeric(cell.value),delta=modeChanged()||a===null||b===null?'—':(b-a).toLocaleString('zh-CN',{maximumSignificantDigits:5});for(const value of [cell.label,old.value,cell.value,delta])row.append(el('td','',value));body.append(row);});table.append(body);const params=el('p','lab-tool-note','记录范围：本页滑块与下拉选项。已记录：'+saved.params+(modeChanged()?'。显示方式已改变；差值暂停，恢复记录参数后可直接对照。':''));results.replaceChildren(params,table);window.BookMath?.typeset(results);}
const restore=el('button','','恢复记录参数'),download=el('button','','导出对照 CSV');
for(const button of [restore,download]){button.type='button';button.hidden=true;row.append(button);}
// shortcut: Button-only random seeds need a model state export before full replay is possible.
const parameterRows=()=>controls.map(n=>({id:n.id,label:text(n.labels?.[0]||n.parentElement),value:n.value,display:n.selectedOptions?.[0]?.textContent||n.value}));
const modeChanged=()=>saved.parameters.some(p=>{const n=controls.find(n=>n.id===p.id);return n.tagName==='SELECT'&&n.value!==p.value;});
pin.onclick=()=>{stop(page);const rows=cells(page);if(!rows.length){note.textContent='本页没有汇总读数；可在图表工具中固定当前曲线。';return;}const parameters=parameterRows();saved={rows,parameters,params:parameters.map(n=>n.label+'='+n.display).join('；')};clear.hidden=restore.hidden=download.hidden=false;pin.textContent='更新记录';update();};
clear.onclick=()=>{saved=undefined;results.replaceChildren();clear.hidden=restore.hidden=download.hidden=true;pin.textContent='记录当前读数';};
restore.onclick=()=>{if(!saved)return;stop(page);const ordered=[...controls].sort((a,b)=>Number(b.tagName==='SELECT')-Number(a.tagName==='SELECT'));for(const input of ordered){const parameter=saved.parameters.find(p=>p.id===input.id);input.value=parameter.value;input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));}update();};
download.onclick=()=>{if(!saved)return;stop(page);const current=parameterRows(),readings=cells(page),rows=[['实验',location.pathname,location.hash],['参数','记录','当前'],...saved.parameters.map((n,i)=>[n.label,n.value,current[i].value]),[],['读数','记录','当前','差值'],...readings.map((n,i)=>{const old=saved.rows.find(row=>row.label===n.label),a=numeric(old?.value||''),b=numeric(n.value);return[n.label,old?.value||'',n.value,modeChanged()||a===null||b===null?'':b-a];})];
// Keep text cells literal when a spreadsheet opens the CSV.
const csv=rows.map(row=>row.map(value=>'"'+String(value).replace(/^[=+@−-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),link=el('a');link.href=url;link.download='galaxies-'+(page.id||'experiment')+'-comparison.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);};
sweep.onclick=()=>{if(running.has(page)){stop(page);return;}const input=document.getElementById(select.value);if(input.disabled)return;const min=+input.min,max=+input.max,step=+input.step||1,apply=t=>{input.value=Math.min(max,min+Math.round((max-min)*t/step)*step);input.dispatchEvent(new Event('input',{bubbles:true}));progress.value=t;};if(motion.matches){apply(1);input.dispatchEvent(new Event('change',{bubbles:true}));note.textContent='已按减少动态效果设置直接显示扫描终点。';return;}const run={button:sweep,frame:0,start:performance.now(),last:0};running.set(page,run);sweep.textContent='停止扫描';sweep.setAttribute('aria-pressed','true');const tick=now=>{if(!page.classList.contains('is-active')||document.hidden||motion.matches){stop(page);return;}const t=Math.min(1,(now-run.start)/8000);if(now-run.last>=180||t===1){apply(t);run.last=performance.now();}if(t<1)run.frame=requestAnimationFrame(tick);else{stop(page);input.dispatchEvent(new Event('change',{bubbles:true}));}};run.frame=requestAnimationFrame(tick);};
controls.forEach(n=>n.addEventListener('change',()=>{stop(page);sync();if(saved)update();}));
inputs.forEach(n=>{n.addEventListener('pointerdown',()=>stop(page));n.addEventListener('keydown',()=>stop(page));});select.onchange=()=>{stop(page);sync();};const observer=new MutationObserver(()=>{if(saved)update();});page.querySelectorAll('.readout-row,.readouts,.extension-readouts,#reservoirs,#clock-chart').forEach(n=>observer.observe(n,{subtree:true,childList:true,characterData:true}));tools.set(page,{update,details,anchor,sync});}
function start(){createDrawer();document.querySelectorAll('.reader-slide').forEach(attach);syncDrawer();}
document.addEventListener('visibilitychange',()=>{if(document.hidden)[...running.keys()].forEach(stop);});document.addEventListener('reader:pagechange',()=>{closeDrawer();for(const page of running.keys())if(!page.classList.contains('is-active'))stop(page);start();});motion.addEventListener('change',()=>{if(motion.matches)[...running.keys()].forEach(stop);});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
